}

export async function gameConfigApply(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("game config: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);

  const family = familyFor(server);
  const schema = schemaFor(family);
  if (!family || !schema) {
    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
  }

  const variant = server.gameVariant ?? schema.defaultVariant;
  const realApply = familyRealApplyEnabled(family);

  // -------------------------------------------------------------------------
  // Simulation is a SANDBOX affordance and MUST NEVER run in production.
  //
  // Until 2026-07-26 it did: production has no ENABLE_REAL_GAMECFG, so every real
  // customer request fell through to the block below, stamped an `_appliedAt`
  // marker, and notified them "Game settings applied on <hostname>" — with the
  // "(sandbox)" suffix suppressed, because SANDBOX is false on production. So the
  // customer changed their difficulty or slot count, was told it was applied, and
  // nothing on the server had changed.
  //
  // Identical in kind to the SSL bug fixed the same day, where production wrote a
  // certificate row as ACTIVE with an invented expiry while no certbot had run:
  // the system asserting an outcome it never performed. A change we did not apply
  // is a FAILURE, and it must say so loudly enough that an operator notices the
  // flag is missing.
  // -------------------------------------------------------------------------
  if (!realApply && !SANDBOX) {
    throw new Error(
      "Game settings could not be applied: real application is switched off on this " +
        "server (ENABLE_REAL_GAMECFG is not set), so nothing was written to the game " +
        "server and your settings are NOT in effect. Please contact support."
    );
  }

  if (!realApply) {
    const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
    const marker = {
      _appliedVariant: variant,
      _appliedAt: new Date().toISOString(),
      _configVersion: GAME_CONFIG_VERSION,
      _sandbox: SANDBOX,
    };

    await db.server.update({
      where: { id: server.id },
      data: { gameConfig: { ...existing, ...marker } as any },
    });

    await notify(
      server.userId,
      `Game settings applied on ${server.hostname}`,
      `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
      `/dashboard/servers/${server.id}?tab=game settings`
    );
    return;
  }

  // -------------------------------------------------------------------------
  // REAL PATH — gated behind ENABLE_REAL_GAMECFG. Everything below is wrapped so
  // a failure notifies the user but never throws out of the handler — EXCEPT
  // the one outcome that must reach an operator: a server that was running
  // before the apply and could not be brought back afterwards.
  //
  // RUN-STATE SEMANTICS (2026-10-01, after the tomatikk incident — see
  // lib/game-runtime.ts planAfterConfigApply): the run state is probed BEFORE
  // and AFTER the apply, and the job reconciles the two:
  //   - running before, down after        → started again (and failed loudly if it can't be)
  //   - stopped before, started by apply  → stopped again, and the customer is told so
  //   - stopped before                    → left stopped, and the customer is told so
  //   - running, needs a restart          → restarted when "Apply & restart" was chosen,
  //                                         otherwise the customer is told a restart is needed
  // Before this, a Minecraft settings save on a stopped server rewrote
  // server.properties, restarted nothing, and reported "applied" — while the
  // dashboard said "Online" over a game that was not running.
  // -------------------------------------------------------------------------
  const payload = (job.payload ?? {}) as { restart?: boolean; changed?: string[]; source?: string };
  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
  const valid = validateConfig(family, existing);
  // `existing` also holds the `_`-prefixed markers; validateConfig drops unknown
  // keys, so `values` is exactly the schema fields keyed on the game's own keys.
  const values = valid.ok ? valid.values : {};

  const rtServer = (await db.server.findUnique({ where: { id: server.id }, select: RUNTIME_SERVER_SELECT })) as RuntimeServer | null;
  const before: RuntimeProbeResult | null = rtServer ? await probeGameRuntime(rtServer, { external: false }) : null;
  const wasRunning = serviceRunning(before?.probe);

  let outcome: ApplyOutcome = { ok: false, applied: [], notes: [] };
  try {
    outcome = await applyRealConfig(server, family, values);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error(`[game-config] real apply failed on ${server.hostname}:`, e);
    outcome = { ok: false, applied: [], notes: [`Apply failed: ${msg}`] };
  }

  // Reconcile the run state.
  const after: RuntimeProbeResult | null = rtServer ? await probeGameRuntime(rtServer, { external: false }) : null;
  const plan = planAfterConfigApply({
    wasRunning,
    isRunning: serviceRunning(after?.probe),
    restartedDuringApply: restartedBetween(before?.probe, after?.probe),
    restartRequested: payload.restart === true,
    // A job with no `changed` list (auto-queued at provision) is treated as
    // "something may have changed" — but is never restarted unless asked.
    hasChanges: payload.changed ? payload.changed.length > 0 : true,
    liveApplied: outcome.notes.some((n) => /Pushed live settings via RCON/.test(n)),
    // Recorded intent wins; with none on record a crash (failed unit) is not a
    // choice, while a clean "inactive" is treated as one (the conservative read).
    stoppedByChoice:
      rtServer?.gameRuntime?.intent === "stopped"
        ? true
        : rtServer?.gameRuntime?.intent === "running" || before?.state === "crashed"
          ? false
          : undefined,
  });
  const unit = safeUnitName(after?.probe.unit ?? before?.probe.unit);
  const runNotes: string[] = [];
  let recoverFailed: string | null = null;
  if (plan.action !== "none" && unit && !SANDBOX) {
    const verb = plan.action === "restore-stop" ? "stop" : plan.action === "restart" ? "restart" : "start";
    try {
      const r = await withServerSsh(server as unknown as SftpServer, (conn) =>
        sshExec(conn, `systemctl ${verb} '${unit}' >/dev/null 2>&1; echo "NXCR:$?:$(systemctl is-active '${unit}' 2>/dev/null)"`, SETUP_TIMEOUT_MS)
      );
      const m = /NXCR:(\d+):(\w*)/.exec(r.stdout);
      const ok = !!m && m[1] === "0" && (verb === "stop" ? m[2] !== "active" : m[2] === "active");
      if (ok && verb !== "stop") {
        const port = await waitForGamePort(server as unknown as ControlServer, controlSpec(family)?.powerStartTimeoutMs ?? 60_000, 4_000);
        if (port && !port.ok) {
          runNotes.push(`${plan.note} The service is running, but the game wasn't answering yet when we checked — it may still be loading.`);
        } else runNotes.push(plan.note);
      } else if (ok) runNotes.push(plan.note);
      else {
        const msg = `Tried to ${verb} the server after applying settings, but it is "${m?.[2] || "unknown"}".`;
        runNotes.push(msg);
        if (plan.action === "recover-start") recoverFailed = msg;
      }
    } catch (e) {
      const msg = `Could not ${verb} the server after applying settings: ${String((e as Error)?.message ?? e).slice(0, 160)}`;
      runNotes.push(msg);
      if (plan.action === "recover-start") recoverFailed = msg;
    }
  } else if (plan.note) {
    runNotes.push(plan.action === "none" || unit ? plan.note : `${plan.note} (We couldn't find the game service to act on — use the power controls.)`);
  }

  // Refresh the runtime cache so the badge matches what we just did.
  if (rtServer) {
    const final = await probeGameRuntime(rtServer).catch(() => null);
    if (final) await saveRuntime(server.id, final);
  }

  // Always record the applied-marker (even on partial/soft failure) so the portal
  // reflects the attempt, and note whether the real push succeeded. Re-read the
  // row first: `_serviceState` and other markers may have been written while
  // this ran, and spreading the stale copy would erase them.
  const marker = {
    _appliedVariant: variant,
    _appliedAt: new Date().toISOString(),
    _configVersion: GAME_CONFIG_VERSION,
    _sandbox: SANDBOX,
    _real: true,
    _realOk: outcome.ok && !recoverFailed,
  };
  try {
    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
    const freshCfg = (fresh?.gameConfig as Record<string, unknown> | null) ?? existing;
    await db.server.update({
      where: { id: server.id },
      data: { gameConfig: { ...freshCfg, ...marker } as any },
    });
  } catch (e) {
    console.error("[game-config] marker update failed", e);
  }

  const detail = [...outcome.applied, ...outcome.notes, ...runNotes].join(" ");
  await notify(
    server.userId,
    recoverFailed
      ? `Settings applied, but ${server.hostname} did not come back up`
      : outcome.ok
        ? `Game settings applied on ${server.hostname}`
        : `Game settings partially applied on ${server.hostname}`,
    `${schema.label} (${variant}) — ${detail || "no changes were made."}`,
    `/dashboard/servers/${server.id}?tab=game settings`
  );
  if (recoverFailed) {
    // A server we left worse off than we found it is an operator problem, not a notification.
    await noRetry(job.id);
    throw new Error(`game config: server was running before the apply and is not now — ${recoverFailed}`);
  }
}

