type Values = Record<string, string | number | boolean>;
type ApplyOutcome = { ok: boolean; applied: string[]; notes: string[] };

/** The minimal Server shape the real path needs to open an SSH connection. */
export type SshServer = {
  id: string;
  rootPassword: string | null;
  rootPasswordEnc?: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
  node?: { publicIp: string } | null;
  gameVariant?: string | null;
};

/**
 * Connect to the game-server VM (host/port derived exactly like the file manager,
 * user "root", password `rootPassword`), run `fn`, and always close the session.
 */
function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    const target = connectionTarget(server as any);
    if (!target) {
      reject(new Error("server is not reachable yet — connection details are pending"));
      return;
    }
    const password = serverRootPassword(server);
    if (!password) {
      reject(new Error("server has no root password set"));
      return;
    }

    const conn = new Client();
    let settled = false;
    const finish = (err: Error | null, val?: T) => {
      if (settled) return;
      settled = true;
      try {
        conn.end();
      } catch {
        /* best-effort */
      }
      if (err) reject(err);
      else resolve(val as T);
    };

    conn.on("ready", () => {
      conn.sftp((err, sftp) => {
        if (err) return finish(err);
        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
      });
    });
    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
    conn.connect({
      host: target.host,
      port: target.port,
      username: "root",
      password,
      readyTimeout: CONNECT_TIMEOUT_MS,
    });
  });
}

/** Read a remote text file, or null if it does not exist. */
function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
  return new Promise((resolve, reject) => {
    sftp.readFile(path, (err, data) => {
      if (err) {
        // ENOENT / no such file → null; anything else is a real error.
        const code = (err as NodeJS.ErrnoException).code;
        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
          return resolve(null);
        }
        return reject(err);
      }
      resolve(data.toString("utf8"));
    });
  });
}

/** Write a remote text file (overwrites). */
function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
  return new Promise((resolve, reject) => {
    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
  });
}

/** Write a remote binary file (overwrites) — same as sftpWrite but skips utf8 re-encoding. */
function sftpWriteBinary(sftp: SFTPWrapper, path: string, content: Buffer): Promise<void> {
  return new Promise((resolve, reject) => {
    sftp.writeFile(path, content, (err) => (err ? reject(err) : resolve()));
  });
}

/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
function execRemote(conn: Client, cmd: string, timeoutMs = EXEC_TIMEOUT_MS): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      const timer = setTimeout(() => {
        try {
          stream.close();
        } catch {
          /* ignore */
        }
      }, timeoutMs);
      stream
        .on("close", (code: number) => {
          clearTimeout(timer);
          resolve({ code: code ?? 0, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
    });
  });
}

/**
 * Locate the first existing path: try explicit candidates via `test -f`, then a
 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
 * Non-destructive — only reads.
 */
async function remoteLocate(
  conn: Client,
  candidates: string[],
  findRoots: string[],
  findName: string
): Promise<string | null> {
  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
  const findExpr = findRoots.length
    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
    : "true";
  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
  return hit ?? null;
}

/** Escape a value for single-quoted shell use. */
function shq(s: string): string {
  return s.replace(/'/g, "'\\''");
}

/**
 * The systemd unit that supervises this family's game container, or null if the
 * guest has none.
 *
 * Every game family's setup script is rewritten at PROVISION time by
 * worker/index.ts's `wrapDockerGameService()` into `docker create` plus a
 * `<hint>.service` unit (`ExecStart=docker start -a <container>`,
 * `Restart=always`, `RestartSec=5`) — and that wrapper deliberately STRIPS
 * docker's own `--restart` policy, in its own words because "leaving both in
 * place makes the two supervisors fight over a crash-looping process". So on
 * every game server this platform provisions, systemd — not docker — owns the
 * container's lifecycle, and any apply path that stops or recreates a container
 * MUST go through it.
 *
 * Returns null when no unit resolves (a server provisioned before that wrapper
 * shipped, or a setup script that didn't match its `docker run -d --name X`
 * shape). There, docker's own restart policy is the only supervisor there is
 * and has to be preserved rather than replaced.
 *
 * The hints come from `lib/game-control.ts`'s per-family `controlSpec` — the
 * same list `worker/game-control.ts`'s power buttons resolve against, and the
 * same list `wrapDockerGameService` names the unit from ([0]) — so this can
 * never drift from the unit that actually got installed.
 */
async function resolveGameUnit(conn: Client, family: string): Promise<string | null> {
  const hints = controlSpec(family)?.serviceHints ?? [];
  if (!hints.length) return null;
  const probe = hints
    .map((h) => `systemctl cat '${shq(h)}.service' >/dev/null 2>&1 && { echo '${shq(h)}.service'; exit 0; };`)
    .join(" ");
  const { stdout } = await execRemote(conn, probe);
  const hit = stdout
    .split(/\r?\n/)
    .map((s) => s.trim())
    .find((s) => s.endsWith(".service"));
  return hit ?? null;
}

/** Dispatch to the correct family renderer. Exported for direct, real-server
 *  verification of a family's real-apply path (see REAL_APPLY_FAMILIES's own
 *  comment for what "confirmed" means) — not called externally otherwise. */
export async function applyRealConfig(server: SshServer, family: string, values: Values): Promise<ApplyOutcome> {
  return withSsh(server, async (conn, sftp) => {
    switch (family) {
      case "minecraft":
        return applyMinecraft(conn, sftp, values, server);
      case "rust":
        return applyRust(conn, sftp, values);
      case "valheim":
        return applyValheim(conn, sftp, values, server.gameVariant ?? "vanilla");
      case "cs2":
        return applyCs2(conn, sftp, values);
      case "palworld":
        return applyPalworld(conn, sftp, values);
      case "bedrock":
        return applyBedrock(conn, sftp, values);
      case "dayz":
        return applyDayZ(conn, sftp, values);
      case "fivem":
        // Feature-flagged family (lib/fivem.ts). File-based cfg renderer —
        // NOT in REAL_APPLY_FAMILIES until live-verified, same rule as dayz.
        return applyFivem(conn, server.id, values);
      default:
        return { ok: false, applied: [], notes: [`No real apply implemented for "${family}".`] };
    }
  });
}

