const MINECRAFT_CONTAINER = "mc";
// no customer was ever bitten by it, but turning the flag on without fixing
// this first would have shipped that same bug to everyone.
//
// The only durable way to change these settings is to recreate the container
// with updated environment variables. Secrets (ADMIN_PASSWORD, which also
// gates RCON) are written to an --env-file over SFTP and referenced by path —
// never passed as `-e KEY=value` on a command line, where they would sit in
// plaintext in `ps aux`/shell history on the customer's own VM (the same
// hardening already applied by hand to sausaugepro's live fix the same day).
// Uses the exact fixed flags prisma/catalog.ts's Palworld template provisions
// with — this function is already Palworld-specific, so it can assume them
// rather than rediscovering a container it will recreate anyway.
// ---------------------------------------------------------------------------

const PALWORLD_CONTAINER = "palworld";

/** Schema field key → Palworld env var name + how to format the value. */
const PALWORLD_ENV_MAP: Record<string, { env: string; format: (v: string | number | boolean) => string }> = {
  difficulty: { env: "DIFFICULTY", format: (v) => String(v) },
  "death-penalty": { env: "DEATH_PENALTY", format: (v) => String(v) },
  pvp: { env: "IS_PVP", format: (v) => (bool(v) === "true" ? "True" : "False") },
  "exp-rate": {
    env: "EXP_RATE",
    format: (v) => {
      const n = Number(v);
      return Number.isFinite(n) ? n.toFixed(6) : String(v);
    },
  },
  "player-caps": { env: "PLAYERS", format: (v) => String(v) },
  "pal-box-import": { env: "ALLOW_GLOBAL_PALBOX_IMPORT", format: (v) => (bool(v) === "true" ? "True" : "False") },
  "pal-box-export": { env: "ALLOW_GLOBAL_PALBOX_EXPORT", format: (v) => (bool(v) === "true" ? "True" : "False") },
  // The image's own official escape hatch (see start.sh): when true, boot skips
  // regenerating PalWorldSettings.ini entirely (only copies a default template
  // if the file is completely empty) — the only way to give a customer a
  // config file that genuinely survives restarts. Found live 2026-09-05.
  "raw-config-mode": { env: "DISABLE_GENERATE_SETTINGS", format: (v) => (bool(v) === "true" ? "True" : "False") },
  // COMMUNITY/SERVER_NAME — see lib/game-config.ts's matching schema fields'
  // doc comment for the full incident (ticket cmuncjvl91exshlhswni8r8bc,
  // 2026-09-30: a customer's PS5 players couldn't join her live server —
  // console Palworld can only discover a dedicated server via this in-game
  // browser, and COMMUNITY defaults to false on the image itself). Unlike the
  // other booleans in this map (formatted "True"/"False" to match
  // PalWorldSettings.ini's own capitalization), COMMUNITY is NOT an ini key —
  // it's read directly by the docker image's own entrypoint, whose docs
  // (docusaurus/docs/getting-started/configuration/server-settings.md) and
  // shipped `.env.example` both spell it lowercase ("true"/"false"), so it's
  // formatted to match that, not the ini convention.
  "community-servers": { env: "COMMUNITY", format: (v) => (bool(v) === "true" ? "true" : "false") },
  "server-name": { env: "SERVER_NAME", format: (v) => String(v) },
};

async function applyPalworld(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  const envMap = await readContainerEnv(conn, PALWORLD_CONTAINER);
  if (!envMap) {
    return { ok: false, applied: [], notes: [`Could not find the "${PALWORLD_CONTAINER}" container — nothing was changed.`] };
  }

  const applied: string[] = [];
  for (const [key, val] of Object.entries(v)) {
    const mapping = PALWORLD_ENV_MAP[key];
    if (!mapping || val == null) continue;
    envMap.set(mapping.env, mapping.format(val));
    applied.push(key);
  }
  if (applied.length === 0) {
    return { ok: true, applied: [], notes: ["No changes to apply."] };
  }

  await writeEnvFile(conn, sftp, "/root/palworld.env", envMap);

  // Ports + volume exactly as prisma/catalog.ts provisions them, except RCON,
  // which is bound to loopback rather than 0.0.0.0 — the platform's own RCON
  // tunnels to 127.0.0.1 over SSH, so nothing needs it published.
  const res = await recreateGameContainer(conn, {
    family: "palworld",
    container: PALWORLD_CONTAINER,
    runFlags: "-p 8211:8211/udp -p 127.0.0.1:25575:25575/tcp -v /opt/palworld:/palworld --env-file /root/palworld.env",
    image: "thijsvanloef/palworld-server-docker",
  });
  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };

  return {
    ok: true,
    applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`],
    notes: ["Your server restarted briefly to apply these — any connected players were disconnected and can rejoin now."],
  };
}

