export function applyGameControlSecrets(
  setupScript: string,
  secrets: Record<string, string>,
): string {
  let out = setupScript;
  for (const [key, value] of Object.entries(secrets)) {
    const re = new RegExp(`-e\\s+${key}=(?:'[^']*'|"[^"]*"|\\S*)`);
    if (!re.test(out)) continue;
    const escaped = value.replace(/'/g, `'\\''`);
    out = out.replace(re, `-e ${key}='${escaped}'`);
  }
  return out;
}

export function applyGameConfigEnv(
  setupScript: string,
  family: string | null,
  gameConfig: Record<string, unknown> | null | undefined,
): string {
  if (!family || !gameConfig) return setupScript;
  const schema = schemaFor(family);
  if (!schema) return setupScript;
  let out = setupScript;
  for (const field of schema.fields) {
    const raw = gameConfig[field.key];
    if (raw === undefined || raw === null) continue;
    // envKey lets a readable schema key (e.g. "world") differ from the
    // literal docker env var name the image expects (e.g. "WORLD_NAME") —
    // see ConfigField.envKey's doc comment in lib/game-config.ts.
    const envName = field.envKey ?? field.key;
    const re = new RegExp(`-e\\s+${envName}=(?:'[^']*'|"[^"]*"|\\S*)`);
    if (!re.test(out)) continue; // this field isn't docker-env-driven in this script — leave it alone
    // A BLANK identity value never overrides a real catalog one (2026-10-02,
    // projectzomboid-syep3t): validateConfig fills every missing field with its
    // schema default, PZ's ADMIN_USERNAME default was "", and this line then
    // turned the catalog's `-e ADMIN_USERNAME=admin` into `-e ADMIN_USERNAME=''`
    // — the game exits on start with `invalid username given to
    // "-adminusername"`, forever. Blank means "no choice made" here.
    if (String(raw).trim() === "" && isIdentityEnvKey(envName)) {
      const current = scriptEnvValue(out, envName);
      if (current !== null && current.trim() !== "") continue;
    }
    const escaped = String(raw).replace(/'/g, `'\\''`);
    out = out.replace(re, `-e ${envName}='${escaped}'`);
  }
  return out;
}

/**
 * If a GAME OsTemplate's setupScript installs the game via a detached
 * `docker run -d --name <container> ...` (true for every game image today —
 * see the OsTemplate rows for minecraft/terraria/ark/etc., all `docker run -d`),
 * rewrite the invocation to `docker create` and append a generated systemd unit
 * that starts/stops the container. Also caps the container's log driver
 * (`--log-opt max-size=10m --log-opt max-file=3`) — see the comment at the
 * `createCmd` line below for why.
 *
 * WHY THIS EXISTS: the whole game control panel — GAME_POWER start/stop/restart,
 * GAME_BACKUP, log tailing (lib/game-control.ts + worker/game-control.ts) —
 * resolves the running game exclusively via `systemctl cat <serviceHint>` /
 * `journalctl -u <unit>`. A bare `docker run -d` creates no systemd unit at all,
 * so every one of those lookups comes back empty and every control action fails
 * silently, on every game family, on every order. Found 2026-08-26 diagnosing a
 * customer's Terraria server (cmt9ss7ln000xhlrx0gch9fcx) that could never be
 * started/stopped from the dashboard even though PROVISION had completed
 * successfully — the container was in fact running, just entirely invisible to
 * systemd.
 *
 * The generated unit is named after the family's FIRST serviceHint, not the
 * docker container's own `--name` — the two don't always match (minecraft's
 * image runs as container "mc" but its control-spec hints are "minecraft" /
 * "minecraft-server") — so `systemctl cat <hint>` resolves regardless of what an
 * individual image's setup script happened to call its container.
 *
 * Intentionally conservative: any setupScript that doesn't match the exact
 * `docker run -d --name X ...` shape (or any non-game family, e.g. the
 * LAMP/WordPress/Caddy panel images that already install a real native systemd
 * service) is returned completely unchanged.
 *
 * Moved here from worker/index.ts 2026-09-24 (alongside `buildGameSetupScript`
 * below) so worker/game-control.ts — which worker/index.ts itself imports, so
 * it cannot import anything back from worker/index.ts without a circular
 * dependency — can also build a real reinstall script for the Danger Zone's
 * wipe/reinstall action. Purely a relocation: behavior is unchanged.
 */
export function wrapDockerGameService(setupScript: string, family: string | null): string {
  if (!isGameFamily(family)) return setupScript;
  const unitName = controlSpec(family)?.serviceHints[0];
  if (!unitName) return setupScript;

  const re = /docker run\s+(?:-d|--detach)\b(.*?)\s+--name[= ]("?)([A-Za-z0-9_.-]+)\2(.*)$/.exec(setupScript.trim());
  if (!re) return setupScript;
  const [full, before, , containerName, after] = re;
  const matchIndex = setupScript.indexOf(full);
  if (matchIndex < 0) return setupScript;

  // Strip docker's own restart policy — systemd now owns restart semantics for
  // this container, and leaving both in place makes the two supervisors fight
  // over a crash-looping process.
  const cleanedAfter = after.replace(/\s*--restart(?:=|\s+)\S+/, "");
  // Cap the container's json-file log driver. No game image's setupScript ever
  // set this, so a crash-looping container (systemd restarting it every 5s
  // forever — see RestartSec above) grows an unbounded log file. Root-caused
  // live 2026-09-17 on projectzomboid-kc0kcr: its docker json log alone had
  // grown to ~28 GB (on top of ~28.5 GB of rsyslog spamming its own
  // "no space left on device" write failures once the disk filled), filling
  // the 77 GB root disk to 100% and taking the game server down. This is the
  // single construction point every game family's `docker run` is rewritten
  // through, so applying the cap here covers all of them at once rather than
  // editing each family's setupScript individually. 10m x 3 files = a 30 MB
  // ceiling per container regardless of how long or how hard it crash-loops.
  const createCmd = `docker create --name ${containerName} --log-opt max-size=10m --log-opt max-file=3${before}${cleanedAfter}`
    .replace(/\s+/g, " ")
    .trim();

  const prefix = setupScript.slice(0, matchIndex);
  // FIRST-BOOT RELIABILITY (2026-10-02, docs/PROVISIONING-FIRST-BOOT-RCA-2026-10-02.md):
  // the container used to be created by ONE `docker create` whose implicit image
  // pull had no retry. valheim-gjjrv9's pull died ~50 s in, the script carried
  // on, installed the unit, and valheim.service restarted 85 times against "No
  // such container" while nothing anywhere tried the pull again. Now:
  //   - the create (and so the pull) is retried with backoff inside the guest;
  //     layers that finished downloading are kept by dockerd, so a retry resumes;
  //   - it is idempotent: a container already built from THIS exact command is
  //     kept, one built from a different command (an earlier attempt with a
  //     broken config, e.g. a blank ADMIN_USERNAME) is replaced — so a re-run
  //     re-applies a corrected config instead of repeating the broken start;
  //   - progress/failure is written to /var/lib/nxeon/game-setup.state, which
  //     the worker polls with short SSH reads (lib/provision-guard.ts
  //     startupProbeCommand) instead of guessing from the outside.
  const cfgHash = createHash("sha256").update(createCmd).digest("hex").slice(0, 16);
  const header = [
    "mkdir -p /var/lib/nxeon",
    `nx_state() { echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) $*" >> /var/lib/nxeon/game-setup.state; }`,
    // One setup run at a time (cloud-init's and a worker re-run can overlap on
    // a slow first boot): the second waits, then finds the container present.
    "exec 9>/var/lib/nxeon/game-setup.lock; flock -w 1800 9 || true",
    "echo $$ > /var/lib/nxeon/game-setup.pid",
    "trap 'rm -f /var/lib/nxeon/game-setup.pid' EXIT",
    `nx_state "setup started"`,
    "nx_create_cmd() {",
    createCmd,
    "}",
    "nx_game_create() {",
    `  if docker container inspect ${containerName} >/dev/null 2>&1 && [ "$(cat /var/lib/nxeon/game-container.cfg 2>/dev/null)" = "${cfgHash}" ]; then nx_state "container present"; return 0; fi`,
    `  docker rm -f ${containerName} >/dev/null 2>&1 || true`,
    "  nx_n=0",
    "  while :; do",
    "    nx_n=$((nx_n+1))",
    `    nx_state "creating container (attempt $nx_n of ${CREATE_ATTEMPTS})"`,
    `    if nx_create_cmd; then echo "${cfgHash}" > /var/lib/nxeon/game-container.cfg; nx_state "container created"; return 0; fi`,
    `    if [ "$nx_n" -ge ${CREATE_ATTEMPTS} ]; then nx_state "failed: docker create (image pull) failed ${CREATE_ATTEMPTS} times"; return 1; fi`,
    "    sleep $((nx_n*15))",
    "  done",
    "}",
  ].join("\n");
  const unit = [
    `cat > /etc/systemd/system/${unitName}.service <<'NXUNIT'`,
    "[Unit]",
    `Description=Nxeon game service (docker: ${containerName})`,
    "After=docker.service",
    "Requires=docker.service",
    // Never let the start rate limit refuse a customer's own Start/Restart;
    // hammering is bounded by the restart backoff below instead.
    "StartLimitIntervalSec=0",
    "",
    "[Service]",
    `ExecStart=/usr/bin/docker start -a ${containerName}`,
    `ExecStop=/usr/bin/docker stop -t 30 ${containerName}`,
    "Restart=always",
    "RestartSec=5",
    // systemd >= 254 (Ubuntu 24.04 ships 255): back off 5s -> 120s across
    // consecutive automatic restarts, so a game that exits on start (PZ with a
    // blank admin username, 40 restarts in 20 min) stops hammering the node.
    // Older systemd ignores both keys with a warning.
    "RestartSteps=5",
    "RestartMaxDelaySec=120",
    "TimeoutStartSec=0",
    "",
    "[Install]",
    "WantedBy=multi-user.target",
    "NXUNIT",
    "systemctl daemon-reload",
    `systemctl enable --now ${unitName}`,
    // Keep the script's exit status = the enable's (GAME_REINSTALL reads it).
    `nx_rc=$?; if docker container inspect ${containerName} >/dev/null 2>&1; then nx_state "ready"; else nx_state "failed: no container after setup"; fi; (exit $nx_rc)`,
  ].join("\n");

  return `${header}\n${prefix}nx_game_create || { tail -n 1 /var/lib/nxeon/game-setup.state 2>/dev/null | grep -q failed || nx_state "failed: setup step before the container (see /var/log/nxeon-setup.log)"; }\n${unit}`;
}

/** In-guest `docker create` (= image pull) attempts before the setup gives up; the worker can re-run it after. */
export const CREATE_ATTEMPTS = 6;

/**
 * Catalog placeholder values for admin/RCON secrets that are the SAME on every
 * server of a family (prisma/seed-wave*.ts ship `changeme12`; images ship
 * `CHANGEME` / `docker`). Anyone who has read the seed files — or guessed —
 * knows them.
 */
export const WEAK_DEFAULT_SECRETS = new Set(["changeme12", "changeme", "CHANGEME", "docker", "admin", "password"]);

/**
 * Admin-/RCON-grade env vars only — never join passwords (those are what the
 * customer hands their players, and are left exactly as configured).
 */
export function isAdminSecretEnvKey(envKey: string): boolean {
  if (!/(ADMIN|RCON)/.test(envKey)) return false;
  return /(PASS|PW)/.test(envKey);
}

function scriptEnvValue(script: string, envKey: string): string | null {
  const m = new RegExp(`-e\\s+${envKey}=('[^']*'|"[^"]*"|\\S*)`).exec(script);
  if (!m) return null;
  return m[1].replace(/^['"]|['"]$/g, "");
}

/**
 * Which schema fields of this family are admin/RCON secrets that the customer
 * left blank AND whose catalog placeholder is a weak shared default — i.e. the
 * server would otherwise boot with the same admin password as every other
 * server of that family. Returns schema FIELD keys; provision() mints a value
 * for each and persists it into Server.gameConfig, so it is (a) substituted by
 * applyGameConfigEnv like any customer value, (b) visible to the customer in
 * Settings, and (c) stable across PROVISION retries and GAME_REINSTALL.
 * Platform RCON is unaffected: it reads the password back out of the running
 * container's env (lib/game-control.ts `docker-env`).
 *
 * Found 2026-10-01: e.g. Project Zomboid ships `ADMIN_USERNAME=admin
 * ADMIN_PASSWORD=changeme12`, and ARK / ARK SA / Icarus / Soulmask / L4D2 /
 * TF2 ship the same `changeme12` as their admin/RCON password.
 */
export function adminSecretFieldsToMint(
  family: string | null,
  rawSetupScript: string | null,
  gameConfig: Record<string, unknown> | null | undefined,
): string[] {
  if (!family || !rawSetupScript) return [];
  const schema = schemaFor(family);
  if (!schema) return [];
  const out: string[] = [];
  for (const f of schema.fields) {
    if (f.type !== "string") continue;
    const envKey = f.envKey ?? f.key;
    if (!isAdminSecretEnvKey(envKey)) continue;
    const current = scriptEnvValue(rawSetupScript, envKey);
    if (current === null || !WEAK_DEFAULT_SECRETS.has(current)) continue;
    const chosen = gameConfig ? gameConfig[f.key] : undefined;
    if (chosen !== undefined && chosen !== null && String(chosen).trim() !== "" && !WEAK_DEFAULT_SECRETS.has(String(chosen))) continue;
    out.push(f.key);
  }
  return out;
}

/**
 * Backstop for admin/RCON env vars with NO schema field (nothing can be
 * persisted for the customer): if the final script still carries a weak
 * shared default, replace it with a fresh per-server value. Same
 * rotate-per-build rule as Palworld/Rust/CS2 below.
 */
export function rotateWeakAdminSecrets(setupScript: string): string {
  const re = /-e\s+([A-Z0-9_]+)=('[^']*'|"[^"]*"|\S*)/g;
  const secrets: Record<string, string> = {};
  let m: RegExpExecArray | null;
  while ((m = re.exec(setupScript))) {
    const value = m[2].replace(/^['"]|['"]$/g, "");
    if (isAdminSecretEnvKey(m[1]) && WEAK_DEFAULT_SECRETS.has(value)) secrets[m[1]] = generatePassword();
  }
  return Object.keys(secrets).length ? applyGameControlSecrets(setupScript, secrets) : setupScript;
}

/**
 * Env vars that name an ACCOUNT (an admin user name), where an empty value is
 * not "no account" but an invalid one the game refuses to start with.
 */
export function isIdentityEnvKey(envKey: string): boolean {
  return /(^|_)(ADMIN_?)?USER(_?NAME)?$/.test(envKey) || /ADMIN_?NAME$/.test(envKey);
}

/** The value a blank identity field gets: the catalog's own (if real), else "admin". */
export const DEFAULT_ADMIN_USERNAME = "admin";

/**
 * Schema fields of this family that name an admin ACCOUNT, are docker-env-driven
 * in its script, and are blank in the server's config — with the value
 * provision() should persist for each (so the customer sees the real admin user
 * name in Settings, and every later rebuild uses it). Pairs with
 * adminSecretFieldsToMint, which handles the matching password.
 */
export function blankIdentityDefaults(
  family: string | null,
  rawSetupScript: string | null,
  gameConfig: Record<string, unknown> | null | undefined,
): Record<string, string> {
  if (!family || !rawSetupScript) return {};
  const schema = schemaFor(family);
  if (!schema) return {};
  const out: Record<string, string> = {};
  for (const f of schema.fields) {
    if (f.type !== "string") continue;
    const envKey = f.envKey ?? f.key;
    if (!isIdentityEnvKey(envKey)) continue;
    const current = scriptEnvValue(rawSetupScript, envKey);
    if (current === null) continue;
    const chosen = gameConfig ? gameConfig[f.key] : undefined;
    if (chosen !== undefined && chosen !== null && String(chosen).trim() !== "") continue;
    out[f.key] = current.trim() !== "" ? current.trim() : DEFAULT_ADMIN_USERNAME;
  }
  return out;
}

/** One per-server secret, same generator as the family-specific ones below. */
export function mintGameSecret(): string {
  return generatePassword();
}

