/**
 * Extract the docker `--name X` container name from a family's RAW (pre-wrap)
 * `docker run -d --name X ...` setupScript — the exact same regex
 * `wrapDockerGameService` above uses, exposed separately for
 * `gameReinstall` (worker/game-control.ts), which needs the real container
 * name to `docker rm -f` the old one before recreating it. Returns null if the
 * script doesn't match that shape (defensive; every current game setupScript
 * does).
 */
export function dockerContainerNameFrom(setupScript: string): string | null {
  const re = /docker run\s+(?:-d|--detach)\b.*?\s+--name[= ]("?)([A-Za-z0-9_.-]+)\1/.exec(setupScript.trim());
  return re ? re[2] : null;
}

/**
 * Extract every `-v hostpath:containerpath` HOST-side path from a family's
 * RAW setupScript — sourced straight from the real `docker run -v ...` flags
 * (never guessed), so these are exactly the directories the game's own
 * container persists data to and the only ones a genuine "wipe" needs to
 * clear. Host paths never contain a colon in any current family's script, so
 * matching up to the first `:` reliably isolates the host side even when the
 * container side is itself quoted-with-spaces (The Isle's setupScript does
 * this: `-v /opt/theisle:"/home/steam/.../The Isle Dedicated Server"`).
 *
 * Safety-guarded, not just parsed: only returns paths that are both
 * `isSafeRemotePath` AND at least two segments under `/opt/` (every real game
 * mount observed in prisma/seed-wave*.ts is `/opt/<family>[/subdir]`) — this
 * is deliberately narrower than `isSafeRemotePath` alone so a malformed or
 * hand-edited OsTemplate row can never make a "wipe" target something as
 * broad as `/`, `/opt`, `/home`, or `/root`.
 */
export function dockerHostMountsFrom(setupScript: string): string[] {
  const out: string[] = [];
  const re = /-v\s+([^\s:]+):/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(setupScript))) {
    const p = m[1];
    if (isSafeRemotePath(p) && /^\/opt\/[A-Za-z0-9_.-]{2,}(\/[A-Za-z0-9_.-]+)*$/.test(p) && !out.includes(p)) {
      out.push(p);
    }
  }
  return out;
}

