 * GAME_CONFIG job to apply them. Refuses while another job is in flight.
 */
export async function saveGameConfig(
  serverId: string,
  variant: string,
  values: Record<string, unknown>,
  opts?: { restart?: boolean }
): Promise<{ error?: string; ok?: boolean; changed?: number; restart?: boolean }> {
  const { user, server } = await ownedServer(serverId);

  const family = familyFor(server);
  const schema = schemaFor(family);
  if (!family || !schema) {
    return { error: "This server doesn't support game settings." };
  }

  if (!isValidVariant(family, variant)) {
    return { error: "Pick a valid server type for this game." };
  }

  const validated = validateConfig(family, values);
  if (!validated.ok) return { error: validated.error };

  // FiveM (feature-flagged): seal a newly pasted Cfx.re key (blank = keep the
  // saved one) and enforce the plan/licence slot cap — lib/fivem-license.ts.
  let fivemKeyChanged = false;
  if (family === "fivem") {
    const fx = prepareFivemConfig({
      values: validated.values,
      previous: (server.gameConfig as Record<string, unknown> | null) ?? {},
      planSlots: server.gamePlan?.slots ?? null,
      requireKey: false,
    });
    if (!fx.ok) return { error: fx.error };
    validated.values = fx.values;
    fivemKeyChanged = fx.keyChanged;
  }

  // Minecraft: only type × version combinations that actually exist (lib/mcjars/availability.ts).
  if (family === "minecraft") {
    const combo = await checkMinecraftCombo(variant, String(validated.values.VERSION ?? "1.21.1"));
    if (!combo.ok) return { error: combo.message };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

