  // `validated.values` over the whole blob, which silently erased
  // `_serviceState` (GAME_POWER's record that the customer stopped the game) —
  // half of why the 2026-09-30 tomatikk dashboard flipped back to "Online"
  // over a stopped game the moment its owner saved a setting.
  const previous = (server.gameConfig as Record<string, unknown> | null) ?? {};
  const markers = Object.fromEntries(Object.entries(previous).filter(([k]) => k.startsWith("_")));
  const prevValid = validateConfig(family, previous);
  const prevValues = prevValid.ok ? prevValid.values : {};
  const changed = Object.keys(validated.values).filter((k) => prevValues[k] !== validated.values[k]);
  if ((server.gameVariant ?? schema.defaultVariant) !== variant) changed.push("variant");
  if (fivemKeyChanged) changed.push("sv_licenseKey");
  const restart = opts?.restart === true;

  await db.server.update({
    where: { id: server.id },
    data: { gameVariant: variant, gameConfig: { ...markers, ...validated.values } as any },
  });
  await db.job.create({ data: { type: "GAME_CONFIG", serverId: server.id, payload: { restart, changed, source: "customer" } } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "gameserver.config",
      detail: `${serverId} family=${family} variant=${variant} changed=${changed.join(",") || "none"}${restart ? " restart=yes" : ""}`,
    },
  });

  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, changed: changed.length, restart };
}
