        cur = con.execute("UPDATE whitelist SET password=? WHERE role=7 AND username=? AND password=?", (job["new"], job["user"], job["expect"]))
        con.commit()
        print("NXUPD:%d" % cur.rowcount)
finally:
    con.close()
`.trim();

export type ZGuest = {
  exec(cmd: string, timeoutMs?: number): Promise<{ code: number; stdout: string; stderr: string }>;
  writeFile(path: string, content: string): Promise<void>;
};
export type ZDeps = {
  /** The systemd unit supervising the game container (resolveGameUnit), or null. */
  resolveUnit(): Promise<string | null>;
  /** waitForGamePort, bound to the server. null = no port known. */
  waitPort(): Promise<{ ok: boolean } | null>;
  hash?: (pw: string) => Promise<string>;
  verifyHash?: (pw: string, hash: string) => Promise<boolean>;
};
export type ZOutcome = { ok: boolean; applied: string[]; notes: string[]; restarted?: boolean };

const sq = (s: string) => s.replace(/'/g, "'\\''");
const LONG = 120_000;

export async function applyZomboidAdmin(
  guest: ZGuest,
  values: Record<string, string | number | boolean>,
  deps: ZDeps,
  opts?: { changed?: string[] },
): Promise<ZOutcome> {
  const pw = String(values.ADMIN_PASSWORD ?? "");
  const secrets: string[] = [pw];
  const redact = (s: string) => secrets.filter((x) => x.length >= 1).reduce((acc, x) => acc.split(x).join("***"), s).slice(0, 300);
  const notLive = (opts?.changed ?? []).filter((k) => !(PZ_LIVE_FIELDS as readonly string[]).includes(k) && !k.startsWith("_"));
  const tail = notLive.length
    ? [`Saved but not applied to the running game: ${notLive.join(", ")}. Only the admin password is applied live for Project Zomboid.`]
    : [];
  const fail = (...notes: string[]): ZOutcome => ({ ok: false, applied: [], notes: [...notes.map(redact), ...tail] });

  if (!pw.trim()) {
    return { ok: true, applied: [], notes: ["The admin password is blank, so the existing admin password was left unchanged.", ...tail] };
  }
  const bad = pzPasswordError(pw);
  if (bad) return fail(`${bad} Nothing was changed on your server.`);

  // 1. What is the container really configured with? (read-only)
  const insp = await guest.exec(`docker inspect ${PZ_CONTAINER} --format '{{json .Config.Env}}|{{.Config.Image}}'`);
  if (insp.code !== 0) return fail(`Could not find the "${PZ_CONTAINER}" game container, so the admin password was not changed.`);
  const sep = insp.stdout.trim().lastIndexOf("|");
  let envArr: string[];
  try {
    envArr = JSON.parse(insp.stdout.trim().slice(0, sep));
  } catch {
    return fail("Could not read the game container's settings, so the admin password was not changed.");
  }
  const image = insp.stdout.trim().slice(sep + 1) || PZ_IMAGE_FALLBACK;
  const env = new Map<string, string>();
  for (const e of envArr) {
    const i = e.indexOf("=");
    if (i > 0) env.set(e.slice(0, i), e.slice(i + 1));
  }
  env.delete("PATH");
  for (const k of ["ADMIN_PASSWORD"]) if (env.get(k)) secrets.push(env.get(k)!);
  const serverName = env.get("SERVER_NAME") || "servertest";
  const adminUser = env.get("ADMIN_USERNAME") ?? "";
  if (!/^[A-Za-z0-9_.-]{1,64}$/.test(serverName) || !adminUser.trim() || /[\r\n]/.test(adminUser)) {
    return fail("The game's server name or admin account could not be determined, so the admin password was not changed.");
  }
  const db = `${PZ_CONFIG_DIR}/db/${serverName}.db`;

  const unit = await deps.resolveUnit();
  if (!unit || !/^[A-Za-z0-9_.@-]+\.service$/.test(unit)) {
    return fail("Could not find the game's service on the server, so the admin password was not changed.");
  }

  const hashFn = deps.hash ?? ((p: string) => pzPasswordHash(p));
  const checkFn = deps.verifyHash ?? pzPasswordMatches;

  // helpers over the 0600 job file
  const py = async (op: "read" | "write", extra: Record<string, string>) => {
    await guest.exec(`install -m 600 /dev/null '${PZ_JOB_FILE}'`);
    await guest.writeFile(PZ_JOB_FILE, JSON.stringify({ db, user: adminUser, ...extra }));
    try {
      const r = await guest.exec(`python3 -c '${sq(PZ_PY)}' '${PZ_JOB_FILE}' ${op}`, 60_000);
      const out = r.stdout;
      if (/NXNODB/.test(out)) return { nodb: true as const };
      const rows = /NXROWS:(\d+)/.exec(out);
      const upd = /NXUPD:(\d+)/.exec(out);
      const hash = /NXHASH:(\S+)/.exec(out);
      if (r.code !== 0 && !rows && !upd) throw new Error("could not read the account database");
      return { nodb: false as const, rows: rows ? Number(rows[1]) : null, updated: upd ? Number(upd[1]) : null, hash: hash ? hash[1] : null };
    } finally {
      await guest.exec(`rm -f '${PZ_JOB_FILE}'`).catch(() => undefined);
    }
  };

  // 2. Is it already in effect? (then no restart at all)
  let prevHash: string | null = null;
  let dbMissing = false;
  try {
    const cur = await py("read", {});
    if (cur.nodb) dbMissing = true;
    else if (cur.rows !== 1 || !cur.hash) {
      return fail(`The "${adminUser}" admin account was not found in the game's account database, so the admin password was not changed.`);
    } else prevHash = cur.hash;
  } catch (e) {
    return fail(`Could not read the game's account database: ${(e as Error).message}. Nothing was changed.`);
  }
  const envMatches = env.get("ADMIN_PASSWORD") === pw;
  if (envMatches && (dbMissing || (prevHash && (await checkFn(pw, prevHash))))) {
    return { ok: true, applied: [], notes: ["The admin password already matches the running game — nothing to change.", ...tail] };
  }

  // 3. Hash host-side, before anything is stopped.
  const newHash = await hashFn(pw);
  secrets.push(newHash);
  if (prevHash) secrets.push(prevHash);

  const wasActive = ((await guest.exec(`systemctl is-active '${unit}'`)).stdout.trim() === "active");
  let dbChanged = false;
  let containerSwapped = false;

  const rollback = async (): Promise<string[]> => {
    const n: string[] = [];
    try {
      await guest.exec(`systemctl stop '${unit}'`, LONG);
      if (dbChanged && prevHash) {
        const r = await py("write", { new: prevHash, expect: newHash }).catch(() => null);
        if (!r || r.nodb || r.updated !== 1) {
          // Last resort: put the pre-change copy of the database back (the game is stopped).
          const cp = await guest.exec(`cp -p '${sq(db)}.nxbak' '${sq(db)}'`);
          if (cp.code !== 0) n.push("Could not restore the previous admin password hash.");
        }
      }
      if (containerSwapped) {
        const r = await guest.exec(
          `docker rm -f ${PZ_CONTAINER} >/dev/null 2>&1; docker rename ${PZ_CONTAINER}-old ${PZ_CONTAINER}`,
        );
        if (r.code !== 0) n.push("Could not restore the previous game container.");
      }
    } catch (e) {
      n.push(`Rollback hit an error: ${(e as Error).message}`);
    }
    await guest.exec(`rm -f '${PZ_ENV_FILE}'`).catch(() => undefined);
    if (wasActive) {
      const s = await guest.exec(`systemctl start '${unit}'`, LONG).catch(() => null);
      if (!s || s.code !== 0) n.push("Could not start the game again after rolling back.");
    }
    return n;
  };
  const failBack = async (why: string): Promise<ZOutcome> => {
    const extra = await rollback();
    return fail(`${why} Your previous admin password and server were restored.`, ...extra);
  };

  // 4. Stop cleanly so the account database is not being written.
  const stop = await guest.exec(`systemctl stop '${unit}'`, LONG);
  const running = await guest.exec(`docker inspect -f '{{.State.Running}}' ${PZ_CONTAINER} 2>/dev/null`);
  if (stop.code !== 0 || running.stdout.trim() === "true") {
    if (wasActive) await guest.exec(`systemctl start '${unit}'`, LONG).catch(() => undefined);
    return fail("Could not stop the game cleanly, so the admin password was not changed.");
  }

  try {
    // 5. Write: backup, then the admin row.
    if (!dbMissing) {
      const bk = await guest.exec(`cp -p '${sq(db)}' '${sq(db)}.nxbak'`);
      if (bk.code !== 0) return await failBack("Could not back up the account database first.");
      const w = await py("write", { new: newHash, expect: prevHash! });
      dbChanged = w.nodb ? false : w.updated === 1;
      if (w.nodb || w.updated !== 1) return await failBack("The admin account could not be updated.");
    }

    // 6. Keep a recreate/reinstall consistent: same container, new env.
    env.set("ADMIN_PASSWORD", pw);
    await guest.exec(`install -m 600 /dev/null '${PZ_ENV_FILE}'`);
    await guest.writeFile(PZ_ENV_FILE, Array.from(env.entries()).map(([k, v]) => `${k}=${v.replace(/\r?\n/g, " ")}`).join("\n") + "\n");
    const swap = await guest.exec(
      `docker rm -f ${PZ_CONTAINER}-old >/dev/null 2>&1; docker rename ${PZ_CONTAINER} ${PZ_CONTAINER}-old`,
    );
    if (swap.code !== 0) return await failBack("Could not replace the game container.");
    containerSwapped = true;
    const create = await guest.exec(
      `docker create --name ${PZ_CONTAINER} ${PZ_RUN_FLAGS} --env-file '${PZ_ENV_FILE}' '${sq(image)}' >/dev/null`,
      LONG,
    );
    if (create.code !== 0) return await failBack(`Could not create the updated game container (${create.stderr.trim().slice(0, 160)}).`);
    await guest.exec(`rm -f '${PZ_ENV_FILE}'`);

    // 7. Start (only if it was running) and wait for the port.
    const notes: string[] = [];
    if (wasActive) {
      const st = await guest.exec(`systemctl start '${unit}'`, LONG);
      if (st.code !== 0) return await failBack("The game did not start with the new password.");
      const port = await deps.waitPort();
      if (port && !port.ok) {
        const alive = await guest.exec(`docker inspect -f '{{.State.Running}}' ${PZ_CONTAINER} 2>/dev/null`);
        if (alive.stdout.trim() !== "true") return await failBack("The game did not come back up with the new password.");
        notes.push("The game is running but wasn't answering yet when we checked — it may still be loading.");
      }
    }

    // 8. Verify for real: hash from the DB checks out, container env carries it.
    if (!dbMissing) {
      const back = await py("read", {});
      if (back.nodb || back.rows !== 1 || !back.hash || !(await checkFn(pw, back.hash))) {
        return await failBack("Verification failed: the stored admin password did not match what was set.");
      }
    }
    const envBack = await guest.exec(`docker inspect ${PZ_CONTAINER} --format '{{json .Config.Env}}'`);
    let envOk = false;
    try {
      envOk = (JSON.parse(envBack.stdout.trim()) as string[]).includes(`ADMIN_PASSWORD=${pw}`);
    } catch {
      envOk = false;
    }
    if (!envOk) return await failBack("Verification failed: the game container did not carry the new password.");

    await guest.exec(`docker rm -f ${PZ_CONTAINER}-old >/dev/null 2>&1; rm -f '${sq(db)}.nxbak'`);
    return {
      ok: true,
      restarted: wasActive,
      applied: ["Admin password applied and verified."],
      notes: [
        ...(wasActive
          ? ["Your server restarted briefly to apply it — connected players were disconnected and can rejoin now."]
          : ["Your server is stopped, so it was not started; the new admin password is active the next time you press Start."]),
        ...notes,
        ...tail,
      ],
    };
  } catch (e) {
    return await failBack(`Applying the admin password failed (${(e as Error).message}).`);
  }
}

