cd /opt/nxeon-wt-pzadmin; cat > test/zomboid-admin.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import bcrypt from "bcryptjs";
import { applyZomboidAdmin, md5Hex, pzPasswordHash, pzPasswordMatches, type ZGuest } from "../worker/zomboid-admin";
import { REAL_APPLY_FAMILIES, canApplyConfig, fieldAppliesLive } from "../lib/game-config";

const NEW_PW = "N3w-Adm1n-Pass!";
const OLD_PW = "old-secret-pw";
const COST = 4; // fast for tests; scheme identical

const fastHash = (p: string) => pzPasswordHash(p, COST);

/** In-memory guest: a fake docker/systemd/sqlite world driven by the exact commands the module sends. */
function fakeGuest(opts: { active?: boolean; failOn?: RegExp; dbMissing?: boolean; startFailsOnce?: boolean; badWrite?: boolean } = {}) {
  const log: string[] = [];
  const files = new Map<string, string>();
  const st = {
    active: opts.active ?? true,
    hash: bcrypt.hashSync(md5Hex(OLD_PW), COST),
    envPw: OLD_PW,
    container: "new" as "old" | "new",
    hasOld: false,
    startsFailed: 0,
  };
  const origHash = st.hash;
  const env = () => JSON.stringify(["PATH=/x", "SERVER_NAME=servertest", "ADMIN_USERNAME=admin", `ADMIN_PASSWORD=${st.envPw}`, "RCON_PASSWORD=rc", "MAX_PLAYERS=16"]);
  let pendingEnvPw: string | null = null;
  const guest: ZGuest = {
    async writeFile(path, content) {
      log.push(`write ${path}`);
      files.set(path, content);
    },
    async exec(cmd) {
      log.push(cmd.replace(/python3 -c '[^]*?' '/, "python3 -c <PY> '"));
      if (opts.failOn && opts.failOn.test(cmd)) return { code: 1, stdout: "", stderr: `boom ${NEW_PW} ${st.hash}` };
      const ok = (stdout = "") => ({ code: 0, stdout, stderr: "" });
      if (cmd.startsWith("docker inspect projectzomboid --format '{{json .Config.Env}}|")) return ok(`${env()}|indifferentbroccoli/pz`);
      if (cmd.startsWith("docker inspect projectzomboid --format '{{json .Config.Env}}'")) return ok(env());
      if (cmd.includes("{{.State.Running}}")) return ok(st.active ? "true" : "false");
      if (cmd.startsWith("systemctl is-active")) return ok(st.active ? "active\n" : "inactive\n");
      if (cmd.startsWith("systemctl stop")) { st.active = false; return ok(); }
      if (cmd.startsWith("systemctl start")) {
        if (opts.startFailsOnce && st.startsFailed++ === 0) return { code: 1, stdout: "", stderr: "failed" };
        st.active = true; return ok();
      }
      if (cmd.startsWith("install -m 600")) return ok();
      if (cmd.startsWith("cp -p")) return ok();
      if (cmd.includes("docker rename projectzomboid projectzomboid-old")) { st.hasOld = true; st.container = "old"; return ok(); }
      if (cmd.includes("docker rename projectzomboid-old projectzomboid")) { st.container = "old"; pendingEnvPw = null; st.envPw = OLD_PW; return ok(); }
      if (cmd.startsWith("docker create")) {
        const envFile = files.get("/root/projectzomboid.env") ?? "";
        assert.ok(/--env-file '\/root\/projectzomboid.env'/.test(cmd), "env via file, never -e");
        assert.ok(!cmd.includes(NEW_PW), "password not on a command line");
        pendingEnvPw = /ADMIN_PASSWORD=(.*)/.exec(envFile)![1];
        st.envPw = pendingEnvPw; st.container = "new";
        return ok();
      }
      if (cmd.includes("python3 -c")) {
        const job = JSON.parse(files.get("/root/.nx-pz-admin.json")!);
        if (opts.dbMissing) return ok("NXNODB\n");
        if (cmd.endsWith(" read")) return ok(`NXROWS:1\nNXHASH:${st.hash}\n`);
        if (job.expect !== st.hash || opts.badWrite) return ok("NXUPD:0\n");
        st.hash = job.new; return ok("NXUPD:1\n");
      }
      return ok();
    },
  };
  return { guest, log, st, origHash, files };
}
const deps = (over: Partial<Parameters<typeof applyZomboidAdmin>[2]> = {}) => ({
  resolveUnit: async () => "projectzomboid.service",
  waitPort: async () => ({ ok: true }),
  hash: fastHash,
  ...over,
});
const noSecrets = (r: { notes: string[]; applied: string[] }) => {
  const all = JSON.stringify(r);
  assert.ok(!all.includes(NEW_PW) && !all.includes(OLD_PW), "no password in outcome");
  assert.ok(!/\$2[aby]\$/.test(all), "no hash in outcome");
};

test("hash scheme: bcrypt of the lowercase md5 hex digest, $2a$", async () => {
  const h = await pzPasswordHash(NEW_PW, COST);
  assert.match(h, /^\$2a\$\d\d\$.{53}$/);
  assert.equal(h.length, 60);
  assert.equal(md5Hex("abc"), "900150983cd24fb0d6963f7d28e17f72");
  assert.ok(bcrypt.compareSync(md5Hex(NEW_PW), h));
  assert.ok(await pzPasswordMatches(NEW_PW, h));
  assert.ok(!(await pzPasswordMatches("wrong", h)));
  assert.ok(!bcrypt.compareSync(NEW_PW, h), "plaintext itself must not verify (md5 step matters)");
});

test("apply order: stop, backup+write, recreate env, start, then read-back verify", async () => {
  const g = fakeGuest();
  const r = await applyZomboidAdmin(g.guest, { ADMIN_PASSWORD: NEW_PW }, deps());
  assert.equal(r.ok, true, JSON.stringify(r));
  const idx = (re: RegExp) => g.log.findIndex((l) => re.test(l));
  const stop = idx(/^systemctl stop/), cp = idx(/^cp -p/), w = g.log.findIndex((l, i) => i > cp && /python3 -c.* write$/.test(l));
  const create = idx(/^docker create/), start = idx(/^systemctl start/);
  const verify = g.log.findIndex((l, i) => i > start && /python3 -c.* read$/.test(l));
  assert.ok(stop > 0 && stop < cp && cp < w && w < create && create < start && start < verify, g.log.join("\n"));
  assert.ok(await pzPasswordMatches(NEW_PW, g.st.hash));
  assert.equal(g.st.envPw, NEW_PW);
  assert.equal(g.st.active, true);
  assert.ok(g.log.some((l) => /rm -f '\/root\/projectzomboid.env'/.test(l)), "env file with the secret is removed");
  noSecrets(r);
  assert.ok(!g.log.some((l) => l.includes(NEW_PW)), "password never in a command");
});

test("already in effect: no stop, no restart", async () => {
  const g = fakeGuest();
  g.st.hash = await pzPasswordHash(NEW_PW, COST);
  g.st.envPw = NEW_PW;
  const r = await applyZomboidAdmin(g.guest, { ADMIN_PASSWORD: NEW_PW }, deps());
  assert.equal(r.ok, true);
  assert.ok(!g.log.some((l) => /systemctl (stop|start)/.test(l)));
});

test("stopped server stays stopped, change still applied", async () => {
  const g = fakeGuest({ active: false });
  const r = await applyZomboidAdmin(g.guest, { ADMIN_PASSWORD: NEW_PW }, deps());
  assert.equal(r.ok, true, JSON.stringify(r));
  assert.ok(!g.log.some((l) => /^systemctl start/.test(l)));
  assert.equal(g.st.active, false);
  assert.ok(await pzPasswordMatches(NEW_PW, g.st.hash));
});

test("rollback: container create fails -> previous hash + container restored, game restarted", async () => {
  const g = fakeGuest({ failOn: /^docker create/ });
  const r = await applyZomboidAdmin(g.guest, { ADMIN_PASSWORD: NEW_PW }, deps());
  assert.equal(r.ok, false);
  assert.equal(g.st.hash, g.origHash, "previous hash restored");
  assert.equal(g.st.envPw, OLD_PW);
  assert.equal(g.st.active, true, "never left stopped");
  assert.ok(g.log.some((l) => /docker rename projectzomboid-old projectzomboid/.test(l)));
  noSecrets(r);
});

test("rollback: game fails to start -> restored and restarted", async () => {
  const g = fakeGuest({ startFailsOnce: true });
  const r = await applyZomboidAdmin(g.guest, { ADMIN_PASSWORD: NEW_PW }, deps());
  assert.equal(r.ok, false);
  assert.equal(g.st.hash, g.origHash);
  assert.equal(g.st.active, true);
  noSecrets(r);
});

test("rollback: verification mismatch -> restored", async () => {
  const g = fakeGuest();
  const r = await applyZomboidAdmin(g.guest, { ADMIN_PASSWORD: NEW_PW }, deps({ verifyHash: async (_p, h) => h === g.origHash }));
  assert.equal(r.ok, false);
  assert.equal(g.st.hash, g.origHash);
  assert.equal(g.st.active, true);
});

test("account row not updated -> failure, game restarted, nothing claimed", async () => {
  const g = fakeGuest({ badWrite: true });
  const r = await applyZomboidAdmin(g.guest, { ADMIN_PASSWORD: NEW_PW }, deps());
  assert.equal(r.ok, false);
  assert.equal(g.st.active, true);
  assert.deepEqual(r.applied, []);
});

test("no game service / bad password / blank password: honest, nothing touched", async () => {
  const g1 = fakeGuest();
  const r1 = await applyZomboidAdmin(g1.guest, { ADMIN_PASSWORD: NEW_PW }, deps({ resolveUnit: async () => null }));
  assert.equal(r1.ok, false);
  assert.ok(!g1.log.some((l) => /systemctl/.test(l)));
  const g2 = fakeGuest();
  const r2 = await applyZomboidAdmin(g2.guest, { ADMIN_PASSWORD: "pässword" }, deps());
  assert.equal(r2.ok, false);
  assert.equal(g2.log.length, 0);
  const r3 = await applyZomboidAdmin(fakeGuest().guest, { ADMIN_PASSWORD: "  " }, deps());
  assert.equal(r3.ok, true);
  assert.match(r3.notes.join(" "), /unchanged/);
});

test("other changed fields are reported as saved-only, never applied", async () => {
  const g = fakeGuest();
  g.st.hash = await pzPasswordHash(NEW_PW, COST);
  g.st.envPw = NEW_PW;
  const r = await applyZomboidAdmin(g.guest, { ADMIN_PASSWORD: NEW_PW }, deps(), { changed: ["PVP", "ADMIN_USERNAME", "ADMIN_PASSWORD"] });
  assert.match(r.notes.join(" "), /not applied.*PVP, ADMIN_USERNAME/);
});

test("secrets in guest stderr are redacted from reported errors", async () => {
  const g = fakeGuest({ failOn: /^docker create/ });
  const r = await applyZomboidAdmin(g.guest, { ADMIN_PASSWORD: NEW_PW }, deps());
  assert.ok(r.notes.join(" ").includes("***"));
  noSecrets(r);
});

test("family gating: admin password live, other Zomboid fields not", () => {
  assert.ok(REAL_APPLY_FAMILIES.has("projectzomboid"));
  assert.ok(canApplyConfig("projectzomboid"));
  assert.equal(fieldAppliesLive("projectzomboid", "ADMIN_PASSWORD"), true);
  for (const k of ["ADMIN_USERNAME", "PublicName", "PVP", "MaxPlayers", "RCON_PASSWORD"]) assert.equal(fieldAppliesLive("projectzomboid", k), false, k);
  assert.equal(fieldAppliesLive("palworld", "difficulty"), true);
});
